#include "GlueCompressorHardwarePanel.h"
#include <algorithm>
#include <cmath>

namespace {const auto cream=juce::Colour(0xffe9dfcf),cyan=juce::Colour(0xff35e1dc),amber=juce::Colour(0xffffad32),dark=juce::Colour(0xff050b0e);void screw(juce::Graphics&g,float x,float y){g.setGradientFill({juce::Colour(0xff626971),x-7,y-7,juce::Colour(0xff111418),x+7,y+7,false});g.fillEllipse(x-7,y-7,14,14);g.setColour(juce::Colour(0xff07090b));g.drawLine(x-4,y,x+4,y,1.5f);}}
void GlueCompressorHardwarePanel::LookAndFeel::drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float p,float start,float end,juce::Slider&s){auto area=juce::Rectangle<float>((float)x,(float)y,(float)w,(float)h).reduced(9);const auto r=std::min(area.getWidth(),area.getHeight())*.34f;const auto c=area.getCentre();for(int tick=0;tick<31;++tick){const auto a=start+(end-start)*tick/30.0f;const auto i=c+juce::Point<float>(std::sin(a),-std::cos(a))*(r+8),o=c+juce::Point<float>(std::sin(a),-std::cos(a))*(r+12);g.setColour(tick%5==0?cream:cream.withAlpha(.45f));g.drawLine({i,o},tick%5==0?1.5f:1.0f);}g.setGradientFill({juce::Colour(0xff59616a),c.x-r,c.y-r,juce::Colour(0xff090b0e),c.x+r,c.y+r,false});g.fillEllipse(c.x-r,c.y-r,r*2,r*2);g.setColour(juce::Colour(0xff030405));g.drawEllipse(c.x-r,c.y-r,r*2,r*2,3);const auto a=start+p*(end-start);const auto tip=c+juce::Point<float>(std::sin(a),-std::cos(a))*(r*.78f);g.setColour(cream);g.drawLine(c.x,c.y,tip.x,tip.y,3);g.setColour(cyan);g.fillEllipse(tip.x-2.5f,tip.y-2.5f,5,5);g.setFont(juce::FontOptions(12).withStyle("Bold"));g.drawText(s.getTextFromValue(s.getValue()),area.removeFromBottom(18),juce::Justification::centred);}
void GlueCompressorHardwarePanel::LookAndFeel::drawToggleButton(juce::Graphics&g,juce::ToggleButton&b,bool over,bool down){auto a=b.getLocalBounds().toFloat().reduced(2);g.setGradientFill({juce::Colour(0xff3b4248),a.getX(),a.getY(),juce::Colour(0xff090c0f),a.getRight(),a.getBottom(),false});g.fillRoundedRectangle(a,5);g.setColour(over?cream:juce::Colour(0xff59626b));g.drawRoundedRectangle(a,5,1.5f);g.setColour(b.getToggleState()?amber:juce::Colour(0xff2d2418));g.fillEllipse(a.getRight()-13,a.getY()+7,6,6);g.setColour(cream.withAlpha(down?.7f:1));g.setFont(juce::FontOptions(12).withStyle("Bold"));g.drawFittedText(b.getButtonText(),b.getLocalBounds().reduced(6),juce::Justification::centred,2);}
void GlueCompressorHardwarePanel::LookAndFeel::drawButtonBackground(juce::Graphics&g,juce::Button&b,const juce::Colour&,bool over,bool){auto a=b.getLocalBounds().toFloat().reduced(2);g.setGradientFill({juce::Colour(0xff414850),a.getX(),a.getY(),juce::Colour(0xff0a0d10),a.getRight(),a.getBottom(),false});g.fillRoundedRectangle(a,5);g.setColour(over?cream:juce::Colour(0xff59626b));g.drawRoundedRectangle(a,5,1.5f);}
void GlueCompressorHardwarePanel::LookAndFeel::drawButtonText(juce::Graphics&g,juce::TextButton&b,bool,bool){g.setColour(cream);g.setFont(juce::FontOptions(12).withStyle("Bold"));g.drawText(b.getButtonText(),b.getLocalBounds(),juce::Justification::centred);}
GlueCompressorHardwarePanel::GlueCompressorHardwarePanel(){const std::array<juce::Component*,10>all{&threshold,&attack,&release,&ratio,&makeup,&inButton,&autoButton,&autoReleaseButton,&hpfButton,&resetButton};for(auto*c:all){addAndMakeVisible(c);c->setLookAndFeel(&lookAndFeel);}configure(threshold,"THRESHOLD",-40,10,.1," dBFS",-11.4);configure(attack,"ATTACK",.1,100,.1," ms",10);configure(release,"RELEASE",50,1000,.1," ms",300);configure(ratio,"RATIO",1,20,.1,":1",4);configure(makeup,"MAKEUP",-18,12,.1," dB",0);inButton.setButtonText("IN\nBYPASS");autoButton.setButtonText("AUTO\nMAKEUP");autoReleaseButton.setButtonText("AUTO\nRELEASE");hpfButton.setButtonText("SC HPF\n80 Hz");inButton.setComponentID("in");autoButton.setComponentID("auto");resetButton.setComponentID("reset");autoReleaseButton.setComponentID("automaticRelease");hpfButton.setComponentID("sidechainHpfHz");for(auto*b:{&inButton,&autoButton,&autoReleaseButton,&hpfButton})b->setClickingTogglesState(true);inButton.onClick=[this]{if(module){module->bypassed=!inButton.getToggleState();if(onModuleChanged)onModuleChanged();repaint();}};autoButton.onClick=[this]{write("autoMakeup",autoButton.getToggleState()?1:0);};autoReleaseButton.onClick=[this]{write("automaticRelease",autoReleaseButton.getToggleState()?1:0);release.setEnabled(!autoReleaseButton.getToggleState());};hpfButton.onClick=[this]{write("sidechainHpfHz",hpfButton.getToggleState()?80:0);};resetButton.onClick=[this]{if(!module)return;module->parameters["thresholdDbfs"]=-11.4;module->parameters["attackMs"]=80;module->parameters["releaseMs"]=300;module->parameters["ratio"]=1.1;module->parameters["makeupGainDb"]=0;module->parameters["autoMakeup"]=0;module->parameters["automaticRelease"]=0;module->parameters["sidechainHpfHz"]=0;refreshFromModule();if(onModuleChanged)onModuleChanged();};}
GlueCompressorHardwarePanel::~GlueCompressorHardwarePanel(){for(auto*c:std::array<juce::Component*,10>{&threshold,&attack,&release,&ratio,&makeup,&inButton,&autoButton,&autoReleaseButton,&hpfButton,&resetButton})c->setLookAndFeel(nullptr);}
void GlueCompressorHardwarePanel::configure(juce::Slider&s,const char*name,double lo,double hi,double step,const char*suffix,double midpoint){s.setName(name);s.setComponentID(name);s.setRange(lo,hi,step);if(midpoint>lo&&midpoint<hi)s.setSkewFactorFromMidPoint(midpoint);s.setTextValueSuffix(suffix);s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);const char*key=juce::String(name)=="THRESHOLD"?"thresholdDbfs":juce::String(name)=="ATTACK"?"attackMs":juce::String(name)=="RELEASE"?"releaseMs":juce::String(name)=="RATIO"?"ratio":"makeupGainDb";s.onValueChange=[this,&s,key]{if(!refreshing)write(key,s.getValue());};}
void GlueCompressorHardwarePanel::write(const char*key,double value){if(!module)return;module->parameters[key]=value;if(onModuleChanged)onModuleChanged();repaint();}double GlueCompressorHardwarePanel::read(const char*key,double fallback)const{if(!module)return fallback;const auto i=module->parameters.find(key);return i==module->parameters.end()?fallback:i->second;}
void GlueCompressorHardwarePanel::setModule(dozi::core::MasteringModulePlan*m){module=m;if(module){module->parameters.try_emplace("autoMakeup",0);module->parameters.try_emplace("automaticRelease",0);module->parameters.try_emplace("sidechainHpfHz",80);}refreshFromModule();}
void GlueCompressorHardwarePanel::setTelemetry(std::optional<dozi::core::ProcessorTelemetry>t){telemetry=std::move(t);repaint();}
void GlueCompressorHardwarePanel::setLiveMetering(double inputDbfs,double outputDbfs,double gainReductionDb,bool active){liveInputDbfs=inputDbfs;liveOutputDbfs=outputDbfs;liveGainReductionDb=gainReductionDb;liveMeteringActive=active;if(!telemetry)telemetry.emplace();telemetry->type=dozi::core::MasteringModuleType::broadbandCompressor;telemetry->inputPeakDbfs=active?inputDbfs:-100.0;telemetry->outputPeakDbfs=active?outputDbfs:-100.0;telemetry->maximumGainReductionDb=active?gainReductionDb:0.0;repaint();}
void GlueCompressorHardwarePanel::refreshFromModule(){refreshing=true;threshold.setValue(read("thresholdDbfs",-11.4),juce::dontSendNotification);attack.setValue(read("attackMs",80),juce::dontSendNotification);release.setValue(read("releaseMs",300),juce::dontSendNotification);ratio.setValue(read("ratio",1.1),juce::dontSendNotification);makeup.setValue(read("makeupGainDb",0),juce::dontSendNotification);inButton.setToggleState(module&&!module->bypassed,juce::dontSendNotification);autoButton.setToggleState(read("autoMakeup",0)>.5,juce::dontSendNotification);autoReleaseButton.setToggleState(read("automaticRelease",0)>.5,juce::dontSendNotification);hpfButton.setToggleState(read("sidechainHpfHz",0)>.5,juce::dontSendNotification);release.setEnabled(!autoReleaseButton.getToggleState());refreshing=false;repaint();}
void GlueCompressorHardwarePanel::paint(juce::Graphics&g){const auto b=getLocalBounds().toFloat();g.setGradientFill({juce::Colour(0xff323941),0,0,juce::Colour(0xff171d23),b.getRight(),b.getBottom(),false});g.fillAll();for(int x=0;x<getWidth();x+=3){g.setColour(juce::Colours::white.withAlpha((x%11)*.0015f));g.drawVerticalLine(x,0,getHeight());}g.setColour(juce::Colour(0xff080c10));g.fillRect(0.f,0.f,38.f,b.getHeight());g.fillRect(b.getRight()-38,0.f,38.f,b.getHeight());for(auto p:{juce::Point<float>{22,22},{b.getRight()-22,22},{22,b.getBottom()-22},{b.getRight()-22,b.getBottom()-22},{22,b.getCentreY()},{b.getRight()-22,b.getCentreY()}})screw(g,p.x,p.y);g.setColour(cream);g.setFont(juce::FontOptions(24).withStyle("Bold"));g.drawText("D O Z I   /   G L U E   C O M P R E S S O R",80,18,getWidth()-160,34,juce::Justification::centred);auto window=juce::Rectangle<float>(245,78,getWidth()-490.f,292);g.setColour(dark);g.fillRoundedRectangle(window,10);g.setColour(juce::Colour(0xff66717a));g.drawRoundedRectangle(window,10,2);const auto input=telemetry?telemetry->inputPeakDbfs:-100,output=telemetry?telemetry->outputPeakDbfs:-100,gr=telemetry?telemetry->maximumGainReductionDb:0;paintLedMeter(g,{268,105,58,225},input,"INPUT");paintLedMeter(g,{getWidth()-326.f,105,58,225},output,"OUTPUT");const auto vw=(window.getWidth()-190)/2;paintVu(g,{348,105,vw,190},gr,"L");paintVu(g,{348+vw+20,105,vw,190},gr,"R");g.setColour(cream);g.setFont(juce::FontOptions(13));g.drawText("GAIN REDUCTION",window.getX(),302,window.getWidth(),20,juce::Justification::centred);g.setColour(cyan);g.setFont(juce::FontOptions(18).withStyle("Bold"));g.drawText(juce::String(gr,1)+" dB GR",window.getX(),324,window.getWidth(),25,juce::Justification::centred);g.setColour(juce::Colour(0xff5c646b));g.drawVerticalLine(getWidth()-185,405,getHeight()-35);for(auto*k:std::array<juce::Slider*,5>{&threshold,&attack,&release,&ratio,&makeup}){g.setColour(cream);g.setFont(juce::FontOptions(13).withStyle("Bold"));g.drawText(k->getName(),k->getX(),k->getY()-18,k->getWidth(),18,juce::Justification::centred);}}
void GlueCompressorHardwarePanel::paintLedMeter(juce::Graphics&g,juce::Rectangle<float>a,double v,const juce::String&label){static constexpr std::array<double,8>t{12,6,0,-6,-12,-18,-24,-36};g.setColour(cream);g.setFont(juce::FontOptions(11).withStyle("Bold"));g.drawText(label,a.removeFromTop(20),juce::Justification::centred);const auto h=(a.getHeight()-14)/8;for(std::size_t n=0;n<t.size();++n){juce::Rectangle<float>s(a.getX()+17,a.getY()+n*(h+2),24,h);const auto c=n<3?amber:cyan;g.setColour(v>=t[n]?c:c.withAlpha(.12f));g.fillRoundedRectangle(s,2);}}
void GlueCompressorHardwarePanel::paintVu(juce::Graphics&g,juce::Rectangle<float>a,double gr,const juce::String&ch){g.setGradientFill({juce::Colour(0xffeadfc6),a.getX(),a.getY(),juce::Colour(0xffb7a98e),a.getRight(),a.getBottom(),false});g.fillRoundedRectangle(a,6);g.setColour(juce::Colour(0xff4c4030));g.drawRoundedRectangle(a,6,2);const auto c=juce::Point<float>(a.getCentreX(),a.getBottom()+18);const auto r=a.getWidth()*.46f;for(int n=0;n<=20;n+=2){const auto angle=juce::degreesToRadians(-55.f+110.f*n/20.f);const auto i=c+juce::Point<float>(std::sin(angle),-std::cos(angle))*(r-(n%4==0?11:6)),o=c+juce::Point<float>(std::sin(angle),-std::cos(angle))*r;g.drawLine({i,o},n%4==0?1.4f:.8f);}const auto angle=juce::degreesToRadians(-55.f+110.f*(float)std::clamp(gr,0.0,20.0)/20.f);const auto tip=c+juce::Point<float>(std::sin(angle),-std::cos(angle))*(r-15);g.setColour(juce::Colour(0xffb51f24));g.drawLine(c.x,c.y,tip.x,tip.y,2.2f);g.setColour(juce::Colour(0xff3a3025));g.fillEllipse(c.x-6,c.y-6,12,12);g.setFont(juce::FontOptions(12).withStyle("Bold"));g.drawText(ch,a.removeFromBottom(24),juce::Justification::centred);}
void GlueCompressorHardwarePanel::resized(){threshold.setBounds(70,430,150,150);attack.setBounds(250,430,150,150);release.setBounds(430,430,150,150);ratio.setBounds(610,430,150,150);makeup.setBounds(790,430,150,150);inButton.setBounds(76,150,120,110);autoButton.setBounds(1010,100,100,58);resetButton.setBounds(1010,172,100,48);autoReleaseButton.setBounds(1000,420,120,58);hpfButton.setBounds(1000,500,120,58);}
